INSERT INTO skinning_loot_template (Entry,ItemType,Item,Chance,QuestRequired,LootMode,GroupId,MinCount,MaxCount,Comment)
SELECT 10264,0,v.Item,v.Chance,0,1,v.GroupId,v.MinCount,v.MaxCount,'VMaNGOS 1fb4909 pool 10264'
FROM (VALUES ROW(4304,2.1277,1,1,1), ROW(8165,14.8936,1,1,1), ROW(8170,53.1915,1,1,2), ROW(8171,8.5106,1,1,1), ROW(15416,21.2766,1,1,1)) AS v(Item,Chance,GroupId,MinCount,MaxCount)
WHERE NOT EXISTS (SELECT 1 FROM skinning_loot_template WHERE Entry=10264)
  AND EXISTS (SELECT 1 FROM creature_template_difficulty WHERE Entry=10264 AND DifficultyID=0 AND SkinLootID=60010);
UPDATE creature_template_difficulty d SET d.SkinLootID=10264 WHERE d.Entry=10264 AND d.DifficultyID=0 AND d.SkinLootID=60010 AND EXISTS (SELECT 1 FROM skinning_loot_template l WHERE l.Entry=10264 AND l.Comment='VMaNGOS 1fb4909 pool 10264');
